/**
 * The one sample image, inline.
 *
 * Image Creation cannot be shown without an image, and making one takes a
 * Foundry deployment, an image model and a credit. So the demo ships a real
 * output of the feature instead: the quarterly business review infographic
 * that the prompt in `demos.ts` asked for, generated by gpt-image-2 at its
 * recorded 1024 x 1024 and re-encoded as JPEG so it is small enough to carry
 * in source. The size is kept because the provenance panel reports it.
 *
 * It is base64 in a module rather than a file on disk because nothing else in
 * the sample data is a file: every other sample is text embedded here, and the
 * packaged app has no assets directory to copy out of.
 */
export const DEMO_IMAGE_JPEG_BASE64 =
  "";
